    @Override protected void onResume(){super.onResume();resumed=true;applyScreenAwake();applyOrientationPreference();getSystemService(android.hardware.display.DisplayManager.class).registerDisplayListener(displayListener,uiHandler);preview.onResume();uiHandler.post(monitorTick);if(checkSelfPermission(Manifest.permission.CAMERA)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.CAMERA},1);else if(previewSurface!=null)controller.open(previewSurface);}
    @Override protected void onPause(){resumed=false;countingDown=false;getSystemService(android.hardware.display.DisplayManager.class).unregisterDisplayListener(displayListener);uiHandler.removeCallbacksAndMessages(null);controller.closeAsync(()->runOnUiThread(()->{if(!resumed)preview.onPause();}));super.onPause();}
    @Override public void onConfigurationChanged(android.content.res.Configuration config){super.onConfigurationChanged(config);controller.displayRotation(getWindowManager().getDefaultDisplay().getRotation()*90);gridOverlay.invalidate();}
