    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(request==1&&results.length>0&&results[0]==PackageManager.PERMISSION_GRANTED&&previewSurface!=null)controller.open(previewSurface);else if(request==1)status("Camera permission needed. Enable it in Android app settings.");if(request==2){boolean granted=checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;preferences.edit().putBoolean("audio",granted).apply();status(granted?"Microphone enabled for future clips":"Video stays silent");}}
    private void select(Style style){preview.compareOriginal(false);selected=style;store.used(style);styleLabel.setText(style.name);preview.setStyle(style,intensity);preferences.edit().putString("selected",style.id).apply();if(carousel!=null)for(int i=0;i<carousel.getChildCount();i++){View card=carousel.getChildAt(i);card.setSelected(style.id.equals(card.getTag()));card.invalidate();}}
    private void refreshCarousel(){if(carousel==null)return;carousel.removeAllViews();for(Style style:new ArrayList<>(store.styles)){Button card=new CameraScreen.FilterButton(this,style.name,thumbnail(style));card.setTag(style.id);card.setOnClickListener(v->select(style));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(78),dp(78));carousel.addView(card,p);}select(selected);}
    private void updateRatioLabel(){preview.setFrameOverlay(FrameOverlay.load(preferences,videoMode));screen.videoFormat(videoShortEdge,videoFps);float ratio=videoMode?videoRatio:photoRatio;ratioButton.setText(ratio==0?"Native":Math.abs(ratio-4f/3)<.01?"4:3":Math.abs(ratio-16f/9)<.01?"16:9":ratio==1?"1:1":Math.abs(ratio-1.5f)<.01?"3:2":"Full");}
    private void changeMode(boolean video){if(countingDown||controller.isBusy()){status("Finish the current capture first");return;}proMode=false;screen.proMode(false);proPanel.setVisibility(View.GONE);controller.proControls(false,200,8000000,controller.whiteBalance());controller.advancedControls(false,controller.whiteBalanceLocked(),preferences.getBoolean("recordWbLock",false)&&controller.hasWhiteBalanceLock(),controller.antiBanding());videoMode=video;preferences.edit().putBoolean("videoMode",video).apply();controller.setFraming(video,video?videoRatio:photoRatio,videoShortEdge,videoFps);shutter.setText(video?"REC":"●");updateRatioLabel();screen.mode(videoMode);status("Configuring "+(video?"video":"photo")+" framing…");}
    private void framing(){if(countingDown||controller.isBusy()){status("Finish the current capture first");return;}Dialog panel=new Dialog(this);panel.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=column();content.setPadding(dp(16),dp(12),dp(16),dp(16));content.setBackgroundColor(0xff121212);LinearLayout heading=row();heading.addView(text(videoMode?"Video framing":"Photo framing",18,Color.WHITE),new LinearLayout.LayoutParams(0,dp(48),1));heading.addView(button("×",v->panel.dismiss()),new LinearLayout.LayoutParams(dp(48),dp(48)));content.addView(heading);float full=preview.getWidth()>0&&preview.getHeight()>0?Math.max(preview.getWidth()/(float)preview.getHeight(),preview.getHeight()/(float)preview.getWidth()):16f/9;String[] labels=videoMode?new String[]{"16:9","4:3","1:1"}:new String[]{"Native","4:3","3:2","16:9","1:1","Full"};float[] ratios=videoMode?new float[]{16f/9,4f/3,1}:new float[]{0,4f/3,3f/2,16f/9,1,full};HorizontalScrollView ratioScroll=new HorizontalScrollView(this);ratioScroll.setHorizontalScrollBarEnabled(false);LinearLayout choices=row();float current=videoMode?videoRatio:photoRatio;for(int i=0;i<labels.length;i++){final float ratio=ratios[i];Button option=button(labels[i],v->{if(videoMode&&!controller.supportsVideo(ratio,videoShortEdge,videoFps)){status("Frame size unsupported by encoder");return;}if(videoMode)videoRatio=ratio;else photoRatio=ratio;preferences.edit().putFloat(videoMode?"videoRatio":"photoRatio",ratio).apply();controller.setFraming(videoMode,ratio,videoShortEdge,videoFps);updateRatioLabel();panel.dismiss();});if(Math.abs(current-ratio)<.01)option.setTextColor(0xffffd54a);choices.addView(option,new LinearLayout.LayoutParams(dp(62),dp(48)));}ratioScroll.addView(choices);content.addView(ratioScroll);LinearLayout timers=row();timers.addView(text("Timer",13,muted));for(int seconds:new int[]{0,3,5,10}){Button timer=button(seconds==0?"Off":seconds+"s",v->{timerSeconds=seconds;preferences.edit().putInt("timer",seconds).apply();panel.dismiss();});if(timerSeconds==seconds)timer.setTextColor(0xffffd54a);timers.addView(timer,new LinearLayout.LayoutParams(0,dp(48),1));}content.addView(timers);Switch grid=new Switch(this);grid.setText("Grid guides");grid.setTextColor(Color.WHITE);grid.setChecked(gridEnabled);grid.setOnCheckedChangeListener((v,on)->{gridEnabled=on;preferences.edit().putBoolean("grid",on).apply();gridOverlay.invalidate();});content.addView(grid,new LinearLayout.LayoutParams(-1,dp(52)));content.addView(button("All camera settings",v->{panel.dismiss();settings();}),new LinearLayout.LayoutParams(-1,dp(48)));panel.setContentView(content);panel.show();Window window=panel.getWindow();if(window!=null){window.setLayout(-1,-2);window.setGravity(Gravity.TOP);window.setBackgroundDrawableResource(android.R.color.transparent);}}
    @Override public void status(String message){runOnUiThread(()->{String value=message==null?"Camera error":message;status.setText(value);status.setVisibility(value.isEmpty()?View.GONE:View.VISIBLE);if(value.startsWith("Saved")||value.contains("digital zoom")||value.startsWith("Focus")||value.endsWith("settings saved"))uiHandler.postDelayed(()->{if(status.getText().toString().equals(value))status.setVisibility(View.GONE);},3000);});}
    @Override public void onBackPressed(){if(proPanel!=null&&proPanel.getVisibility()==View.VISIBLE){proPanel.setVisibility(View.GONE);return;}if(screen!=null&&screen.filterPanel.getVisibility()==View.VISIBLE){screen.filterPanel.setVisibility(View.GONE);return;}super.onBackPressed();}
    @Override public void ready(String profile){status("");runOnUiThread(()->{if(controller.activeCameraId()!=null)preferences.edit().putString("cameraId",controller.activeCameraId()).apply();lightButton.setEnabled(controller.hasFlash());lightButton.setTag(controller.lightEnabled());lightButton.invalidate();screen.zoomTwo.setEnabled(controller.zoomMax()>=2);if(proPanel!=null)proPanel.cameraChanged();applyCameraPreferences();gridOverlay.invalidate();shutter.setEnabled(controller.recordingState()!=RecordingState.PREPARING&&controller.recordingState()!=RecordingState.FINALIZING);});try{try(FileOutputStream f=openFileOutput("device-profile.txt",MODE_PRIVATE)){f.write(profile.getBytes(java.nio.charset.StandardCharsets.UTF_8));}}catch(IOException ignored){}}
    private void takeCapture(){if(countingDown)return;if(videoMode){if(!recording)setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LOCKED);controller.toggleRecording(preferences.getBoolean("audio",false));return;}if(controller.isBusy()){status("Wait for the current capture");return;}if(timerSeconds==0){controller.capture(selected,intensity,preferences.getBoolean("original",true));return;}countingDown=true;long end=android.os.SystemClock.elapsedRealtime()+timerSeconds*1000L;Runnable countdown=new Runnable(){public void run(){if(!countingDown||!resumed)return;long remaining=end-android.os.SystemClock.elapsedRealtime();if(remaining<=0){countingDown=false;controller.capture(selected,intensity,preferences.getBoolean("original",true));}else{status("Capture in "+((remaining+999)/1000)+"…");uiHandler.postDelayed(this,200);}}};countdown.run();}
    @Override public void saved(Uri uri){lastMedia=uri;preferences.edit().putString("lastMedia",uri.toString()).apply();status("Saved to "+(uri.toString().contains("video")?"Movies":"Pictures")+"/Aabhix");loadGalleryThumbnail();}
    private void loadGalleryThumbnail(){Uri uri=lastMedia;if(uri==null||galleryThumbnail==null)return;new Thread(()->{try{Bitmap bitmap=getContentResolver().loadThumbnail(uri,new android.util.Size(128,128),null);runOnUiThread(()->galleryThumbnail.setImageBitmap(bitmap));}catch(Exception ignored){/* The gallery action reports inaccessible/deleted media. */}},"AabhixThumbnail").start();}
    @Override public void recording(boolean active){recording=active;runOnUiThread(()->{if(active)setRequestedOrientation(android.content.pm.ActivityInfo.SCREEN_ORIENTATION_LOCKED);else applyOrientationPreference();shutter.setText(active?"STOP":videoMode?"REC":"●");strength.setEnabled(true);ratioButton.setEnabled(!active);});}
    private void gallery(){if(lastMedia==null){status("No Aabhix capture yet");return;}try{Intent intent=new Intent(Intent.ACTION_VIEW,lastMedia);intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(intent);}catch(Exception e){status("No viewer available for this capture");}}
    private void library(){
        Dialog dialog=new Dialog(this);LinearLayout content=column();content.setBackgroundColor(background);content.setPadding(dp(16),dp(12),dp(16),dp(12));
        TextView heading=text("Style library",27,Color.WHITE);content.addView(heading);content.addView(text("Original SDR grades · photo + video GPU path",11,muted));
        EditText search=edit("Search styles","");search.setSingleLine();content.addView(search);
        Spinner categories=new Spinner(this);List<String> names=new ArrayList<>(Arrays.asList("All","Favorites","Recently used"));for(Style s:store.styles)if(!names.contains(s.category))names.add(s.category);for(String c:store.collections())names.add("Collection: "+c);
        ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,names);categories.setAdapter(adapter);content.addView(categories);
        ScrollView scroll=new ScrollView(this);LinearLayout cards=column();scroll.addView(cards);content.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        Runnable render=()->{cards.removeAllViews();String query=search.getText().toString().toLowerCase(Locale.ROOT),category=(String)categories.getSelectedItem();List<Style> entries=new ArrayList<>(store.styles);
            if("Recently used".equals(category)){List<String> recent=store.recent();entries.sort(Comparator.comparingInt(s->{int i=recent.indexOf(s.id);return i<0?999:i;}));}
            for(Style s:entries){if(!s.name.toLowerCase(Locale.ROOT).contains(query))continue;if("Favorites".equals(category)&&!store.favorites().contains(s.id))continue;if("Recently used".equals(category)&&!store.recent().contains(s.id))continue;if(category.startsWith("Collection: ")&&!store.collection(category.substring(12)).contains(s.id))continue;if(!Arrays.asList("All","Favorites","Recently used").contains(category)&&!category.startsWith("Collection: ")&&!s.category.equals(category))continue;
                LinearLayout card=row();card.setPadding(dp(6),dp(6),dp(6),dp(6));card.setBackgroundColor(surface);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,dp(78));cp.bottomMargin=dp(6);cards.addView(card,cp);
                ImageView thumbnail=new ImageView(this);thumbnail.setImageBitmap(thumbnail(s));card.addView(thumbnail,new LinearLayout.LayoutParams(dp(88),-1));LinearLayout info=column();info.setPadding(dp(12),0,0,0);info.addView(text(s.name+(store.favorites().contains(s.id)?"  ★":""),16,Color.WHITE));info.addView(text(s.category+"  ·  Photo / Video*",11,muted));card.addView(info,new LinearLayout.LayoutParams(0,-1,1));card.setOnClickListener(v->{select(s);dialog.dismiss();});card.setOnLongClickListener(v->{new AlertDialog.Builder(this).setTitle(s.name).setItems(new String[]{"Toggle favorite","Add to collection"},(d,i)->{if(i==0){store.toggleFavorite(s);categories.setSelection(categories.getSelectedItemPosition());card.setAlpha(store.favorites().contains(s.id)?1:.7f);}else collectionDialog(s);}).show();return true;});
            }};
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){render.run();}public void afterTextChanged(Editable e){}});
        categories.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int position,long id){render.run();}public void onNothingSelected(AdapterView<?> p){}});
        content.addView(text("*Compatibility requires a device test. Thumbnails use a cached camera scene when available, otherwise a synthetic chart. Hold a style for favorites/collections.",10,muted));LinearLayout actions=row();actions.addView(button("Import",v->{dialog.dismiss();Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(intent,30);}));actions.addView(button("Create",v->{dialog.dismiss();custom();}));actions.addView(button("Close",v->dialog.dismiss()));content.addView(actions);dialog.setContentView(content);dialog.getWindow().setLayout(-1,-1);dialog.show();dialog.getWindow().setLayout(-1,-1);
    }
    private Bitmap thumbnail(Style s){int w=96,h=96;Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);int[] pixels=new int[w*h];float[] matrix=ColorEngine.matrix(s,1),scratch=new float[3];Bitmap scene=null;if(thumbnailSource!=null&&!thumbnailSource.isRecycled()){int[] crop=FrameGeometry.crop(thumbnailSource.getWidth(),thumbnailSource.getHeight(),1);Bitmap cut=Bitmap.createBitmap(thumbnailSource,crop[0],crop[1],crop[2],crop[3]);scene=Bitmap.createScaledBitmap(cut,w,h,true);scene.getPixels(pixels,0,w,0,0,w,h);if(cut!=thumbnailSource&&cut!=scene)cut.recycle();}for(int y=0;y<h;y++)for(int x=0;x<w;x++){int rgb=scene==null?Color.HSVToColor(new float[]{x*360f/w,.15f+.75f*y/h,.3f+.7f*(1-y/(float)h)}):pixels[y*w+x];pixels[y*w+x]=ColorEngine.apply(rgb,matrix,s.lut,1,scratch);}if(scene!=null&&scene!=thumbnailSource)scene.recycle();b.setPixels(pixels,0,w,0,0,w,h);return b;}
    private void collectionDialog(Style s){EditText name=edit("Collection name","");new AlertDialog.Builder(this).setTitle("Add to collection").setView(name).setPositiveButton("Save",(d,i)->{try{store.addCollection(name.getText().toString(),s);status("Collection saved");}catch(Exception e){status(e.getMessage());}}).setNegativeButton("Cancel",null).show();}
    private void custom(){LinearLayout form=column();form.setPadding(dp(16),0,dp(16),0);EditText name=edit("Original preset name",selected.name+" Custom");form.addView(name);String[] keys={"Saturation 0–2","Contrast 0.1–2","Warmth −0.2–0.2","Tint −0.2–0.2","Fade 0–0.3","Exposure −0.3–0.3"};float[] values={selected.saturation,selected.contrast,selected.warmth,selected.tint,selected.fade,selected.exposure};EditText[] fields=new EditText[6];for(int i=0;i<6;i++){form.addView(text(keys[i],12,muted));fields[i]=edit(keys[i],""+values[i]);fields[i].setInputType(8194|4096);form.addView(fields[i]);}ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle("Create original style").setView(scroll).setPositiveButton("Save",(d,i)->{try{float[] p=new float[6];for(int k=0;k<6;k++)p[k]=Float.parseFloat(fields[k].getText().toString());select(store.saveCustom(name.getText().toString(),p[0],p[1],p[2],p[3],p[4],p[5]));refreshCarousel();}catch(Exception e){status("Preset not saved: "+e.getMessage());}}).setNegativeButton("Cancel",null).show();}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==31&&result==RESULT_OK&&data!=null){java.util.List<Uri> uris=new java.util.ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());new ConfigLibrary(this,this::applyConfig,controller).importUris(uris);return;}if(request!=30||result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();new Thread(()->{try{String title="import.cube";try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())title=c.getString(0);}final String name=title;if(name.toLowerCase(Locale.ROOT).endsWith(".png"))runOnUiThread(()->{if(resumed)new AlertDialog.Builder(this).setTitle("Confirm PNG LUT layout").setMessage("Use only a 512×512 image containing 8×8 tiles of a64³ RGB LUT: red varies across each tile, green down each tile, blue across tiles. Ordinary square photos and other LUT layouts can produce incorrect colors. You can compare with Original after import.").setPositiveButton("Use tiled RGB layout",(d,i)->importSelected(name,uri)).setNegativeButton("Cancel",null).show();});else importSelected(name,uri);}catch(Exception e){status("Import rejected: "+e.getMessage());}},"AabhixImportName").start();}
    private void importSelected(String name,Uri uri){new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("File unavailable");Style style=store.importPreset(name,in);runOnUiThread(()->{select(style);refreshCarousel();status("Imported "+style.name+" · SDR input required");});}catch(Exception e){status("Import rejected: "+e.getMessage());}},"AabhixImport").start();}
