    private void videoProfile(){if(controller.isBusy()||countingDown){status("Finish capture before changing video format");return;}LinearLayout content=column();content.setPadding(dp(12),dp(10),dp(12),dp(10));content.setBackgroundColor(0xff181818);PopupWindow popup=new PopupWindow(content,Math.min(screen.root.getWidth()-dp(20),dp(380)),-2,true);popup.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(0xff181818));popup.setOutsideTouchable(true);popup.setElevation(dp(8));int[] choice={videoShortEdge,videoFps};Runnable[] render=new Runnable[1];render[0]=()->{content.removeAllViews();content.addView(text("Video format",17,Color.WHITE));LinearLayout resolution=row();for(int edge:new int[]{720,1080,2160}){Button option=button(edge==2160?"4K":edge+"p",v->{choice[0]=edge;render[0].run();});boolean available=false;for(int rate:new int[]{15,20,24,25,30,60})if(controller.offersVideo(16f/9,edge,rate))available=true;option.setEnabled(available);if(choice[0]==edge)option.setTextColor(0xffffd54a);resolution.addView(option,new LinearLayout.LayoutParams(0,dp(48),1));}content.addView(resolution);content.addView(text("Frames per second",12,muted));LinearLayout rates=row();for(int fps:new int[]{15,20,24,25,30,60}){Button option=button(""+fps,v->{choice[1]=fps;render[0].run();});option.setPadding(dp(2),0,dp(2),0);option.setEnabled(controller.offersVideo(16f/9,choice[0],fps));if(choice[1]==fps)option.setTextColor(0xffffd54a);rates.addView(option,new LinearLayout.LayoutParams(0,dp(44),1));}content.addView(rates);content.addView(text("AVC SDR · rotate landscape for higher supported sizes",11,muted));LinearLayout actions=row();actions.addView(button("Cancel",v->popup.dismiss()),new LinearLayout.LayoutParams(0,dp(44),1));Button apply=button("Apply",v->{if(!controller.offersVideo(16f/9,choice[0],choice[1]))return;videoShortEdge=choice[0];videoFps=choice[1];videoRatio=16f/9;preferences.edit().putInt("videoShortEdge",videoShortEdge).putInt("videoFps",videoFps).putFloat("videoRatio",videoRatio).apply();popup.dismiss();changeMode(true);});apply.setEnabled(controller.offersVideo(16f/9,choice[0],choice[1]));actions.addView(apply,new LinearLayout.LayoutParams(0,dp(44),1));content.addView(actions);};render[0].run();popup.showAsDropDown(screen.format.getVisibility()==View.VISIBLE?screen.format:screen.aspect,0,dp(4),Gravity.END);}
    private void referenceMode(String name){new AlertDialog.Builder(this).setTitle(name).setMessage(name.equals("Portrait")?"Computational portrait segmentation and depth blur are not implemented in this build. A color preset cannot replace portrait processing.":"Multi-frame night capture and alignment are not implemented in this build. Use Pro with a tripod for a hardware-supported long exposure.").setPositiveButton("Close",null).show();}
    private void moreModes(){if(countingDown||controller.isBusy()){status("Finish capture before changing modes");return;}Dialog dialog=new Dialog(this);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);LinearLayout content=column();content.setPadding(dp(12),dp(12),dp(12),dp(12));content.setBackgroundColor(0xff151515);content.addView(text("More · capture and tools",20,Color.WHITE));String[] labels={"Pro video","Long exposure","Document","Configs","Film frames","LUT library","Watermark","Settings"};Runnable[] actions={()->{changeMode(true);controls();},()->{changeMode(false);controls();proPanel.selectControl("S");},()->{changeMode(false);for(Style style:store.styles)if(style.id.equals("document-mono")){select(style);break;}},this::configs,this::frameStudio,this::library,this::watermarkStudio,this::settings};for(int start=0;start<labels.length;start+=3){LinearLayout row=row();for(int i=start;i<Math.min(start+3,labels.length);i++){final int index=i;row.addView(button(labels[i],v->{dialog.dismiss();actions[index].run();}),new LinearLayout.LayoutParams(0,dp(58),1));}content.addView(row);}content.addView(button("Close",v->dialog.dismiss()));dialog.setContentView(content);dialog.show();if(dialog.getWindow()!=null)dialog.getWindow().setLayout(-1,-2);}
    private void frameStudio(){if(controller.isBusy()||countingDown){status("Finish capture before changing frames");return;}String[] labels={"Off","Cinema 2.39:1 · black bars","Cinema 2.35:1 · black bars","Cinema 1.85:1 · black bars","White photo border","Black border"},ids={"none","cinema239","cinema235","cinema185","white","black"};new AlertDialog.Builder(this).setTitle(videoMode?"Video frame · baked into footage":"Photo frame · original preserved by preference").setItems(labels,(d,i)->{preferences.edit().putString(videoMode?"videoFrame":"photoFrame",ids[i]).apply();preview.setFrameOverlay(new FrameOverlay(ids[i]));}).setNegativeButton("Cancel",null).show();}
    private void configs(){if(controller.isBusy()||countingDown){status("Finish capture before applying configuration");return;}new ConfigLibrary(this,this::applyConfig,controller).show();}
    private void applyConfig(PortableConfig config){if(controller.isBusy()||countingDown){status("Finish capture before applying configuration");return;}try{Map<String,String> values=config.values;Style configStyle=selected;if(values.containsKey("styleId")){configStyle=null;for(Style candidate:store.styles)if(candidate.id.equals(values.get("styleId")))configStyle=candidate;if(configStyle==null)throw new IllegalArgumentException("Import the referenced LUT/style first: "+values.get("styleId"));}String isoValue=values.get("iso");int iso=isoValue==null?controller.manualIso():isoValue.equalsIgnoreCase("auto")?0:Integer.parseInt(isoValue);long exposure=values.containsKey("exposureNs")?Long.parseLong(values.get("exposureNs")):controller.manualExposure();int wb=values.containsKey("wb")?Integer.parseInt(values.get("wb")):controller.whiteBalance();int ev=values.containsKey("evSteps")?Integer.parseInt(values.get("evSteps")):controller.currentEv();if(values.containsKey("exposureNs")&&!values.containsKey("iso")&&iso==0)throw new IllegalArgumentException("Manual shutter requires aabhix.iso or an active manual ISO");if(iso>0&&values.containsKey("evSteps")&&ev!=0)throw new IllegalArgumentException("EV compensation requires automatic exposure");if(values.containsKey("evSteps")&&(ev<controller.evMin()||ev>controller.evMax()))throw new IllegalArgumentException("EV outside this lens range");if((values.containsKey("iso")||values.containsKey("exposureNs"))&&iso>0&&(!controller.hasManualSensor()||controller.isoRange()==null||!controller.isoRange().contains(iso)||controller.exposureRange()==null||!controller.exposureRange().contains(exposure)))throw new IllegalArgumentException("Manual ISO/shutter outside this lens range");boolean validWb=false;for(int mode:controller.whiteBalanceModes())if(mode==wb&&mode>0)validWb=true;if(values.containsKey("wb")&&!validWb)throw new IllegalArgumentException("WB unsupported by this lens");android.content.SharedPreferences.Editor editor=preferences.edit();for(Map.Entry<String,String> entry:values.entrySet()){String key=entry.getKey(),value=entry.getValue();if(key.equals("original")||key.equals("grid")||key.equals("stableVideo")||key.equals("stabilization"))editor.putBoolean(key,Boolean.parseBoolean(value));else if(key.equals("jpegQuality"))editor.putInt(key,Integer.parseInt(value));else if(key.endsWith("Frame"))editor.putString(key,value);}editor.apply();if(values.containsKey("iso")||values.containsKey("exposureNs")||values.containsKey("wb"))controller.proControls(iso>0,iso,exposure,wb);if(values.containsKey("evSteps"))controller.controls(ev,controller.currentZoom(),controller.currentFocus());controller.refreshSettings();gridEnabled=preferences.getBoolean("grid",false);gridOverlay.invalidate();preview.setFrameOverlay(FrameOverlay.load(preferences,videoMode));proPanel.cameraChanged();if(values.containsKey("styleId"))select(configStyle);if(values.containsKey("styleIntensity"))strength.setProgress(Math.round(Float.parseFloat(values.get("styleIntensity"))*100));preferences.edit().putString("lastConfigReport",config.summary()).apply();status("Applied "+values.size()+" mapped values · "+config.unmapped+" private keys retained only");}catch(Exception e){status("Config not applied: "+e.getMessage());}}
    private void pipelineDiagnostics(){controller.runtimeReport(json->{if(!resumed)return;TextView content=text(json,12,Color.LTGRAY);content.setTextIsSelectable(true);ScrollView scroll=new ScrollView(this);scroll.addView(content);new AlertDialog.Builder(this).setTitle("Developer camera diagnostics").setView(scroll).setPositiveButton("Close",null).setNeutralButton("Original preview",(d,i)->{preview.compareOriginal(true);status("Unfiltered preview only · saved output retains the selected style");}).setNegativeButton("Neutral baseline",(d,i)->{select(Style.identity());strength.setProgress(100);controller.controls(0,1,-1);controller.proControls(false,200,8000000,1);controller.advancedControls(false,false,preferences.getBoolean("recordWbLock",false)&&controller.hasWhiteBalanceLock(),controller.antiBanding());controller.light(false);status("Original style · automatic exposure / white balance · 1×");}).show();});}
    private void chooseCamera(){if(countingDown||controller.isBusy()){status("Finish the current capture before selecting a camera");return;}controller.cameraChoices(choices->{if(!resumed)return;String[] labels=new String[choices.size()];for(int i=0;i<labels.length;i++)labels[i]=choices.get(i).label;new AlertDialog.Builder(this).setTitle("Camera / lens · public IDs").setItems(labels,(d,i)->controller.selectCamera(choices.get(i).id)).setNegativeButton("Cancel",null).show();});}
    @Override public void recordingState(RecordingState state){runOnUiThread(()->{boolean preparing=state==RecordingState.PREPARING;boolean finalizing=state==RecordingState.FINALIZING;shutter.setEnabled(!preparing&&!finalizing);if(preparing)status("Preparing recorder…");else if(finalizing)status("Finalizing video…");});}
