    private void orientationSettings(){if(recording||countingDown||controller.isBusy()){status("Finish the current capture before changing orientation");return;}new AlertDialog.Builder(this).setTitle("Orientation").setSingleChoiceItems(new String[]{"Automatic · sensor rotation","Portrait","Landscape"},preferences.getInt("orientation",0),(d,i)->{if(controller.isBusy()||countingDown){status("Finish the current capture first");return;}preferences.edit().putInt("orientation",i).apply();applyOrientationPreference();d.dismiss();}).setNegativeButton("Cancel",null).show();}
