    private void antiFlicker(){int[] modes=controller.antiBandingModes();String[] names=new String[modes.length];String[] labels={"Off","50 Hz","60 Hz","Auto"};for(int i=0;i<modes.length;i++)names[i]=modes[i]<labels.length?labels[modes[i]]:"Mode "+modes[i];new AlertDialog.Builder(this).setTitle("Anti-flicker").setItems(names,(d,i)->{controller.advancedControls(controller.exposureLocked(),controller.whiteBalanceLocked(),preferences.getBoolean("recordWbLock",false)&&controller.hasWhiteBalanceLock(),modes[i]);preferences.edit().putInt("antiBanding",modes[i]).apply();}).setNegativeButton("Cancel",null).show();}
    private void applyCameraPreferences(){preview.setFrameOverlay(FrameOverlay.load(preferences,videoMode));int mode=preferences.getInt("antiBanding",3);boolean found=false;for(int value:controller.antiBandingModes())if(value==mode)found=true;if(!found&&controller.antiBandingModes().length>0)mode=controller.antiBandingModes()[0];controller.advancedControls(controller.exposureLocked()&&controller.hasExposureLock(),controller.whiteBalanceLocked()&&controller.hasWhiteBalanceLock(),preferences.getBoolean("recordWbLock",false)&&controller.hasWhiteBalanceLock(),mode);}
