    @Override public boolean onKeyDown(int code,KeyEvent event){if((code==KeyEvent.KEYCODE_VOLUME_UP||code==KeyEvent.KEYCODE_VOLUME_DOWN)&&preferences.getBoolean("volumeShutter",false)){if(event.getRepeatCount()==0&&resumed)takeCapture();return true;}return super.onKeyDown(code,event);}
    private final Runnable monitorTick=new Runnable(){public void run(){if(!resumed)return;gridOverlay.invalidate();if(proPanel.getVisibility()==View.VISIBLE)proPanel.refresh();try{
        android.hardware.camera2.TotalCaptureResult result=controller.latestResult();if(proMode&&result!=null){Integer iso=result.get(android.hardware.camera2.CaptureResult.SENSOR_SENSITIVITY);Long time=result.get(android.hardware.camera2.CaptureResult.SENSOR_EXPOSURE_TIME);Float focus=result.get(android.hardware.camera2.CaptureResult.LENS_FOCUS_DISTANCE);screen.proReadout.setText("ISO "+(controller.manualIso()==0?"A ":"")+(iso==null?"—":iso)+"   S "+(controller.manualIso()==0?"A ":"")+MonitorMath.shutter(time)+"   EV "+controller.currentEv()+"\n"+(controller.currentFocus()<0?"AF":"MF "+String.format(Locale.ROOT,"%.2fD",focus==null?0:focus))+"   WB "+(controller.whiteBalance()==1?"Auto":"preset "+controller.whiteBalance()));}
        String info=recording?"● REC "+MonitorMath.timecode(controller.recordingElapsed()):"";if(preferences.getBoolean("storageHud",false)){long bytes=new android.os.StatFs(android.os.Environment.getExternalStorageDirectory().getAbsolutePath()).getAvailableBytes();info+="  "+String.format(Locale.ROOT,"%.1f GB free",bytes/1_000_000_000.0);}if(preferences.getBoolean("batteryHud",false)){Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null){int scale=battery.getIntExtra(android.os.BatteryManager.EXTRA_SCALE,0);if(scale>0)info+="  "+battery.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL,0)*100/scale+"%";}}monitorInfo.setText(info.trim());
        long now=android.os.SystemClock.elapsedRealtime();if(preferences.getBoolean("histogram",false)&&!histogramPending&&now>=nextHistogram){histogramPending=true;nextHistogram=now+1500;preview.captureThumbnail(bitmap->{if(bitmap==null){runOnUiThread(()->histogramPending=false);return;}int[] pixels=new int[bitmap.getWidth()*bitmap.getHeight()];bitmap.getPixels(pixels,0,bitmap.getWidth(),0,0,bitmap.getWidth(),bitmap.getHeight());bitmap.recycle();int[][] bins=MonitorMath.histogram(pixels);runOnUiThread(()->{histogramPending=false;if(resumed)monitor.histogram(bins);});});}
    }catch(RuntimeException e){android.util.Log.w("AabhixMonitor","Readout unavailable",e);}uiHandler.postDelayed(this,500);}};
    private void privacy(){new AlertDialog.Builder(this).setTitle("Private by default").setMessage("Everything processes on your phone. This app has no INTERNET or location permission.\n\nPhoto export strips optional JPEG metadata, retaining ICC color data and minimal orientation. Original captures are preserved by default when a styled copy is saved.\n\nVideo receives no location, watermark or user tags by default. Optional text watermarks are visibly baked into recorded footage. Technical container/encoder fields can remain. No blanket metadata-removal claim.\n\nBuilt-in colors are independently created, with no official camera-brand affiliation. HDR, grain, bloom and advanced import adapters are pending.\n\nAabhix 0.11.0 · device compatibility must be tested.").setPositiveButton("OK",null).show();}
